const resetCatalogueEnrichmentBefore = `-- name: ResetCatalogueEnrichmentBefore :execrows
UPDATE search_documents sd
SET enrichment_status = 'pending', enrichment_attempted_at = NULL
WHERE sd.workspace_id = ANY($1::uuid[])
  AND sd.enrichment_status = 'enriched'
  AND COALESCE(sd.enrichment_prompt_version, '') <> $2::text
`

type ResetCatalogueEnrichmentBeforeParams struct {
	CatalogWorkspaceIds []pgtype.UUID
	PromptVersion       string
}

func (q *Queries) ResetCatalogueEnrichmentBefore(ctx context.Context, arg ResetCatalogueEnrichmentBeforeParams) (int64, error) {
	result, err := q.db.Exec(ctx, resetCatalogueEnrichmentBefore, arg.CatalogWorkspaceIds, arg.PromptVersion)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const searchSkills = `-- name: SearchSkills :many
SELECT s.skill_id, s.workspace_id, s.name, s.summary
FROM search_documents s
WHERE s.workspace_id = $1
  AND NOT s.generated
  AND s.tsv @@ websearch_to_tsquery('english', $3::text)
ORDER BY ts_rank_cd(s.tsv, websearch_to_tsquery('english', $3::text)) DESC
LIMIT $2
`

type SearchSkillsParams struct {
	WorkspaceID pgtype.UUID
	Limit       int32
	Query       string
}

type SearchSkillsRow struct {
	SkillID     pgtype.UUID
	WorkspaceID pgtype.UUID
	Name        string
	Summary     string
}

func (q *Queries) SearchSkills(ctx context.Context, arg SearchSkillsParams) ([]SearchSkillsRow, error) {
	rows, err := q.db.Query(ctx, searchSkills, arg.WorkspaceID, arg.Limit, arg.Query)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []SearchSkillsRow
	for rows.Next() {
		var i SearchSkillsRow
		if err := rows.Scan(
			&i.SkillID,
			&i.WorkspaceID,
			&i.Name,
			&i.Summary,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

